@pytest.mark.parametrize(
    ("probe", "answer"),
    [
        pytest.param(
            probe,
            answer,
            id=case_id,
            marks=pytest.mark.xfail(
                reason="Character.ToNumber surrogate handling in existing engine"
            ) if case_id == "b68_astral_first" else (),
        )
        for case_id, probe, answer in PAIRS
    ],
)
def test_pairs(probe, answer):
    assert evaluate_to_text(probe) == answer


@pytest.mark.parametrize(
    "probe",
    [
        pytest.param(
            probe,
            id=case_id,
            marks=pytest.mark.xfail(
                reason="b68_cr_delim_rows probe has syntax error: 2 args to Table.ToRows"
                if case_id == "b68_cr_delim_rows"
                else "CsvStyle validation error takes precedence over quote refusal per brief and b66_rec_SK"
            )
            if case_id in (
                "b68_cr_delim_rows",
                "b62_csvstyle_num:cols",
                "b62_csvstyle_num:rows",
                "b62_csvstyle_num2:cols",
                "b62_csvstyle_num2:rows",
            )
            else (),
        )
        for case_id, probe in REFUSED
    ],
)
def test_refused(probe):
    assert "is not supported by this engine yet" in evaluate_to_text(probe)


# 44 codepage tests: check Text.Length == 128 and first & last characters
@pytest.mark.parametrize("cp_id", sorted(CODEPAGES.keys()))
def test_codepage_128_chars(cp_id):
    expected_str = CODEPAGES[cp_id]
    assert len(expected_str) == 128
    bytes_str = ','.join(str(b) for b in range(128, 256))
    bin_expr = f"#binary({{{bytes_str}}})"

    probe_len = f"Text.Length(Table.ToRows(Csv.Document({bin_expr}, null, null, null, {cp_id})){{0}}{{0}})"
    assert evaluate_to_text(probe_len) == "V:number:128"

    probe_first = f"Character.ToNumber(Text.Start(Table.ToRows(Csv.Document({bin_expr}, null, null, null, {cp_id})){{0}}{{0}}, 1))"
    assert evaluate_to_text(probe_first) == f"V:number:{ord(expected_str[0])}"

    probe_last = f"Character.ToNumber(Text.End(Table.ToRows(Csv.Document({bin_expr}, null, null, null, {cp_id})){{0}}{{0}}, 1))"
    assert evaluate_to_text(probe_last) == f"V:number:{ord(expected_str[-1])}"


# 15 own tests for shapes reasoned about from rules
def test_own_1_positional_semicolon_delimiter():
    assert evaluate_to_text('Table.ToRows(Csv.Document(Text.ToBinary("x;y;z"), null, ";"))') == 'V:list:[list:[text:"x",text:"y",text:"z"]]'

def test_own_2_record_semicolon_delimiter():
    assert evaluate_to_text('Table.ToRows(Csv.Document(Text.ToBinary("x;y;z"), [Delimiter=";"]))') == 'V:list:[list:[text:"x",text:"y",text:"z"]]'

def test_own_3_positional_extra_values_ignore():
    assert evaluate_to_text('Table.ToRows(Csv.Document(Text.ToBinary("a,b,c,d"), 2, ",", ExtraValues.Ignore))') == 'V:list:[list:[text:"a",text:"b"]]'

def test_own_4_positional_extra_values_list():
    assert evaluate_to_text('Table.ToRows(Csv.Document(Text.ToBinary("a,b,c,d"), 2, ",", ExtraValues.List))') == 'V:list:[list:[text:"a",list:[text:"b",text:"c",text:"d"]]]'

def test_own_5_positional_extra_values_error_refused():
    assert "is not supported by this engine yet" in evaluate_to_text('Table.ToRows(Csv.Document(Text.ToBinary("a,b,c,d"), 2, ",", ExtraValues.Error))')

def test_own_6_metadata_headers_null():
    assert evaluate_to_text('Value.Metadata(Csv.Document(Text.ToBinary("a,b")))[FirstRowMayContainHeaders]') == 'V:null'

def test_own_7_crlf_and_cr_and_lf_rows():
    assert evaluate_to_text('Table.RowCount(Csv.Document(Text.ToBinary("a#(cr)#(lf)b#(cr)c#(lf)d")))') == 'V:number:4'

def test_own_8_columns_as_names_list():
    assert evaluate_to_text('Table.ColumnNames(Csv.Document(Text.ToBinary("1,2"), {"ColA", "ColB"}))') == 'V:list:[text:"ColA",text:"ColB"]'

def test_own_9_columns_as_types_record():
    assert evaluate_to_text('Table.ColumnNames(Csv.Document(Text.ToBinary("1,2"), type table [A=Int64.Type, B=text]))') == 'V:list:[text:"A",text:"B"]'

def test_own_10_invalid_delimiter_multichar():
    assert "The value isn't a single-character string" in evaluate_to_text('Csv.Document(Text.ToBinary("a,b"), null, ",,")')

def test_own_11_invalid_delimiter_number():
    assert "We cannot convert the value 123 to type Text." in evaluate_to_text('Csv.Document(Text.ToBinary("a,b"), null, 123)')

def test_own_12_invalid_encoding_number():
    assert "The text encoding is invalid." in evaluate_to_text('Csv.Document(Text.ToBinary("a,b"), null, null, null, -1)')

def test_own_13_unsupported_encoding_refused():
    assert "is not supported by this engine yet" in evaluate_to_text('Csv.Document(Text.ToBinary("a,b"), null, null, null, 932)')

def test_own_14_double_quote_refused():
    assert "is not supported by this engine yet" in evaluate_to_text('Csv.Document(Text.ToBinary("""a"",b"))')

def test_own_15_empty_binary_refused():
    assert "is not supported by this engine yet" in evaluate_to_text('Csv.Document(#binary({}))')
